import asyncio, json, os, re
from playwright.async_api import async_playwright
# Stream C: Practice door (Look / Listen / Flash, My path, Learn it with Bix), lessons, games, grown-ups gate, parent report.
res=[]
def check(label, ok, extra=''): res.append(bool(ok)); print(('PASS ' if ok else 'FAIL ')+label+(('  '+str(extra)) if extra else ''))
HERE=os.path.dirname(os.path.abspath(__file__)); URL='http://localhost:%s/index.html' % os.environ.get('PORT','8765')
SEED=open(os.path.join(HERE,'seed_report.js')).read()
# navigator.share stand-in: records what would be shared
SHARE="(()=>{ window.__shared=[]; navigator.share=(d)=>{ window.__shared.push(d); return Promise.resolve(); }; })()"
async def gate(pg):
    await pg.click('#grownups'); await pg.wait_for_selector('#gate.active')
    await pg.evaluate('window.__gateHold()'); await pg.fill('#gateA', str(await pg.evaluate('window.__gateAnswer'))); await pg.click('#gateOk'); await pg.wait_for_selector('#parent.active'); await pg.wait_for_timeout(300)
async def door(pg):
    await pg.evaluate("App.show('door')"); await pg.wait_for_selector('#door.active'); await pg.wait_for_timeout(250)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
        ctx=await b.new_context(viewport={'width':1180,'height':820}); errs=[]; dialogs=[]
        pg=await ctx.new_page(); pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.on('dialog', lambda d: (dialogs.append(d.message), asyncio.ensure_future(d.dismiss())))
        await pg.add_init_script(SEED); await pg.add_init_script(SHARE)
        await pg.goto(URL); await pg.wait_for_timeout(900)

        # ---- the door draws itself when shown ----
        await door(pg)
        blocks=await pg.eval_on_selector_all('#door .door-block','els=>els.map(e=>e.textContent.trim())')
        check('door: Look, Listen, Flash blocks', blocks==['7+8−4Look','Listen','9Flash'] or [x[-6:].strip() for x in blocks]==['Look','Listen','Flash'], blocks)
        check('door: Bix asks how to play', 'How do you want to play' in (await pg.text_content('#bixDoor .bubble') or ''))
        nodes=await pg.eval_on_selector_all('#doorPath .dp-node','els=>els.map(e=>[e.className.split(" ")[1], e.querySelector(".dp-name").textContent])')
        check('path rod shows only nearby skills: 2 done, current, 2 locked', [n[0] for n in nodes]==['done','done','cur','locked','locked'], nodes)
        check('current skill is Big friends +9…+6 and has the star bead', nodes[2][1].startswith('Big friends') and await pg.locator('#doorPath .dp-node.cur .dp-bead svg').count()>=2)
        check('more skills hinted with … on both sides', await pg.locator('#doorPath .dp-more:has-text("…")').count()==2)
        check('Learn it with Bix button under the current skill', await pg.locator('#doorPath .dp-node.cur #doorLearn').count()==1)
        lh=await pg.eval_on_selector('#doorLearn','e=>e.getBoundingClientRect().height')
        check('Learn it with Bix is a child-size target (>= 60px)', lh>=60, lh)
        sp=await pg.evaluate("(()=>{const b=document.querySelector('#bixDoor .bubble'), drawn=p=>{const c=getComputedStyle(b,p); return c.display!=='none' && !['none','normal'].includes(c.content) && c.maskImage!=='none'}; return {say:b.querySelectorAll('.ws-say').length, after:drawn('::after'), before:drawn('::before')}})()")
        check('door bubble: one speaker mark (no CSS pseudo-element icon)', sp['say']<=1 and not sp['after'] and not sp['before'], sp)
        await pg.click('#doorPath .dp-node.locked .dp-bead >> nth=0'); await pg.wait_for_timeout(200)
        check('tapping a locked bead: Bix explains it is locked', 'Locked' in await pg.text_content('#bixDoor .bubble'))
        await pg.click('#doorPath .dp-node.done .dp-bead >> nth=0'); await pg.wait_for_timeout(200)
        check('tapping a learned bead: Bix praises', 'already know' in await pg.text_content('#bixDoor .bubble'))
        # each block starts its drill mode for the current skill
        for sel, m in (('#doorLook','visual'),('#doorListen','listen'),('#doorFlash','flash')):
            await door(pg); await pg.click(sel); await pg.wait_for_selector('#drill.active', timeout=5000)
            d=await pg.evaluate("window.__drill ? window.__drill() : null")
            check(f'{sel} starts the {m} drill', d and d.get('mode')==m, d and d.get('mode'))
            await pg.click('#exitDrill'); await pg.wait_for_timeout(300)
        # Learn it with Bix -> lesson for the current skill -> back to the door
        await door(pg); await pg.click('#doorLearn'); await pg.wait_for_selector('#lesson.active')
        check('Learn it with Bix opens the lesson for the current skill', (await pg.text_content('#lessonTitle')).startswith('Big friends') and await pg.text_content('#capKind')=='New skill')
        check('lesson: the practice soroban (AbacusInput), rods sized to the lesson', await pg.locator('#lessonAbacus .abx .abx-rod').count()==3 and await pg.locator('#lessonAbacus .sb-rod').count()==0)
        check('lesson intro: beads are read-only while Bix talks', await pg.locator('#lessonAbacus.ab-ro').count()==1)
        check('lesson progress is a row of beads, not a bar', await pg.locator('#lessonSteps .ls-dot').count()>=4 and await pg.locator('#lesson .progressbar').count()==0)
        lines=[]; kinds=[]
        for _ in range(6):
            lines.append(await pg.evaluate("(()=>{const t=document.querySelector('#capText'); return Math.round(t.getBoundingClientRect().height/parseFloat(getComputedStyle(t).lineHeight))})()")); kinds.append(await pg.text_content('#capKind'))
            await pg.click('#lessonNext'); await pg.wait_for_timeout(300)
            if (await pg.text_content('#capKind')).startswith('Watch'): break
        check('lesson intro: the explanation is split into pages of at most 3 lines', len(kinds)>=2 and all(k=='New skill' for k in kinds) and max(lines)<=3 and min(lines)>=1, [kinds, lines])
        check('lesson: Next after the intro pages shows a demonstration', (await pg.text_content('#capKind')).startswith('Watch 1 of'), await pg.text_content('#capKind'))
        check('lesson: the back button is a child-size target (>= 60px)', await pg.eval_on_selector('#exitLesson','e=>e.getBoundingClientRect().height')>=60)
        nd=await pg.evaluate("window.App && Curriculum.BY_ID.bf_add_a.demos.length")
        for _ in range(nd-1): await pg.click('#lessonNext'); await pg.wait_for_timeout(150)
        dots=await pg.eval_on_selector_all('#lessonSteps .ls-dot','els=>els.map(e=>e.className.replace("ls-dot","").trim())')
        check(f'lesson: on "Watch {nd} of {nd}" the first {nd} step beads are filled (done + current)', (await pg.text_content('#capKind'))==f'Watch {nd} of {nd}' and dots[:nd]==['ok']*(nd-1)+['cur'] and all(d=='' for d in dots[nd:]), dots)
        fr=await pg.eval_on_selector_all('#capFriends span','els=>els.map(e=>Math.round(e.getBoundingClientRect().top))')
        check('lesson: friend chips sit on one line', len(fr)==5 and len(set(fr))==1, fr)
        await pg.click('#lessonNext'); await pg.wait_for_timeout(300)
        check('lesson: on "Your turn" the beads can be moved', (await pg.text_content('#capKind')).startswith('Your turn') and await pg.locator('#lessonAbacus.ab-ro').count()==0)
        await pg.click('#exitLesson'); await pg.wait_for_timeout(300)
        check('leaving a lesson started at the door returns to the door', await pg.locator('#door.active').count()==1)

        # ---- games hub and each game ----
        await pg.evaluate("App.goPlay()"); await pg.wait_for_selector('#play.active')
        cards=await pg.eval_on_selector_all('.gcard','els=>els.map(e=>e.dataset.game+":"+e.className)')
        check('play hub: three toy boxes (Toy Table kit)', len(cards)==3 and all('toy-box' in c for c in cards) and await pg.locator('.gcard .gc-lid').count()==3, cards)
        cols=await pg.eval_on_selector_all('.gcard','els=>els.map(e=>e.dataset.game+":"+["red","indigo","mustard","teal"].find(c=>e.classList.contains(c)))')
        check('each game has its own kit colour: Friend Pop red, Bead Detective indigo, Bead Builder mustard', cols==['pop:red','reader:indigo','build:mustard'], cols)
        hub=await pg.text_content('#playCards')
        check('hub cards show no times', not re.search(r'\d\s*s\b|second', hub), hub)
        sp=await pg.evaluate("(()=>{const b=document.querySelector('#bixPlay .bubble'); return {say:b.querySelectorAll('.ws-say svg').length, after:getComputedStyle(b,'::after').content}})()")
        check('Play bubble: exactly one speaker icon', sp['say']==1 and sp['after'] in ('none','normal'), sp)
        check('no countdown bar on the game screen', await pg.locator('#game .gbar, #gameBar').count()==0)
        for g, name in (('pop','Friend Pop'),('reader','Bead Detective'),('build','Bead Builder')):
            await pg.click(f'.gcard[data-game={g}]'); await pg.wait_for_selector('#game.active'); await pg.wait_for_timeout(400)
            check(f'{name} opens', name in await pg.text_content('#gameTitle') and await pg.locator('#gameStage > *').count()>0)
            await pg.wait_for_timeout(2200)
            bub=await pg.evaluate("(()=>{const b=document.querySelector('#bixGame .bubble'), t=b.querySelector('.ws-text'), r=b.getBoundingClientRect(); return {kit:b.classList.contains('ws-bubble'), say:b.querySelectorAll('.ws-say svg').length, w:r.width, lines:Math.round(t.getBoundingClientRect().height/parseFloat(getComputedStyle(t).lineHeight)), on:b.classList.contains('on'), text:t.textContent.trim()}})()")
            heads=await pg.evaluate("[...document.querySelectorAll('#gameStage h1,#gameStage h2,#gameStage .rd-msg,#gameStage .bd-k,#gameStage .pop-hint,#gameTitle')].map(e=>e.textContent.trim())")
            check(f'{name}: Bix uses the kit bubble (speaker mark, >= 320px, <= 2 lines) and does not repeat a heading', bub['kit'] and bub['say']==1 and bub['w']>=320 and 1<=bub['lines']<=2 and bub['on'] and bub['text'] not in heads, [bub, heads])
            bk=await pg.eval_on_selector('#exitGame','e=>e.getBoundingClientRect().height')
            check(f'{name}: back button >= 60px', bk>=60, bk)
            if g=='pop':
                ins=[]; ovl=[]
                for _ in range(12):
                    r=await pg.evaluate("(()=>{const f=document.querySelector('#popField'), fr=f.getBoundingClientRect(), cs=getComputedStyle(f), bl=parseFloat(cs.borderLeftWidth), bt=parseFloat(cs.borderTopWidth); const inner={l:fr.left+bl,t:fr.top+bt,r:fr.right-bl,b:fr.bottom-bt}; const bs=[...f.querySelectorAll('.bub:not(.popped):not(.out)')].map(b=>b.getBoundingClientRect()); const out=bs.filter(b=>b.left<inner.l-1||b.top<inner.t-1||b.right>inner.r+1||b.bottom>inner.b+1).length; let ov=0; for(let i=0;i<bs.length;i++) for(let j=i+1;j<bs.length;j++){ const a=bs[i], c=bs[j], dx=(a.left+a.width/2)-(c.left+c.width/2), dy=(a.top+a.height/2)-(c.top+c.height/2); if (Math.hypot(dx,dy) < a.width-2) ov++; } return [bs.length,out,ov]})()")
                    ins.append(r[1]); ovl.append(r[2]); await pg.wait_for_timeout(350)
                check('Friend Pop: every bubble stays fully inside the frame', sum(ins)==0, ins)
                check('Friend Pop: bubbles never overlap', sum(ovl)==0, ovl)
                w0=await pg.evaluate("document.querySelector('#gameScore').innerHTML"); await pg.wait_for_timeout(1500)
                check('Friend Pop: nothing runs down while she plays (round = 12 friends to find)', await pg.locator('#gameScore .gdot').count()==12 and w0==await pg.evaluate("document.querySelector('#gameScore').innerHTML"))
            if g=='reader':
                await pg.wait_for_selector('#rdCover.on', timeout=8000)
                keys=await pg.eval_on_selector_all('#rdPad .toy-keypad button','els=>els.map(e=>e.dataset.k)')
                check('Bead Detective uses the kit keypad (TOY.keypad): 1-2-3/4-5-6/7-8-9, wide 0, delete; no local copy', keys==['1','2','3','4','5','6','7','8','9','0','del'] and await pg.locator('#rdPad .g-keys, #rdPad .toy-keypad [data-k=go]').count()==0, keys)
                check('games.js has no keypad of its own', '.keypad(el' in open(os.path.join(HERE,'..','games.js')).read() and 'g-keys' not in open(os.path.join(HERE,'..','games.js')).read())
                check('Bead Detective: round teal Check beside the mat (outside the grid), off until a number is typed', await pg.locator('#rdPad .toy-keypad-wrap > .toy-start.g-check[data-k=go]:disabled').count()==1)
                await pg.click('#rdPad [data-k="5"]')
                check('Bead Detective: Check turns on after typing', await pg.locator('#rdPad .g-check:disabled').count()==0)
                bg=await pg.eval_on_selector('#rdCover','e=>getComputedStyle(e).backgroundImage')
                check('Bead Detective cover: plain wood, no striped strip', 'repeating' not in bg, bg[:60])
                check('Bead Detective: the practice soroban, read-only', await pg.locator('#rdAb.ab-ro .abx').count()==1)
                ghost=await pg.evaluate("(async()=>{const c=document.querySelector('#rdCover'), sp=c.querySelector('span'); c.classList.remove('on'); await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))); const o1=+getComputedStyle(sp).opacity; c.classList.add('on'); await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))); const o2=+getComputedStyle(sp).opacity, bg=+getComputedStyle(c).opacity; return [o1,o2,bg]})()")
                check('Bead Detective cover: no ghost eye or "?" over the beads while it opens or closes', ghost[0]==0 and ghost[1]<0.05, ghost)
            if g=='build':
                tb=await pg.eval_on_selector_all('#bdSay, #bdClear','els=>els.map(e=>Math.round(e.getBoundingClientRect().height))')
                check('Bead Builder: Again and Clear are child-size targets (>= 60px)', len(tb)==2 and min(tb)>=60, tb)
                check('Bead Builder: the practice soroban, beads big enough to tap (>= 56px slots)', await pg.locator('#bdAb .abx').count()==1 and await pg.evaluate("(()=>{const r=document.querySelector('#bdAb .abx-hit').getBoundingClientRect(); return r.height>=56})()"))
            await pg.click('#exitGame'); await pg.wait_for_selector('#play.active')
        # no timers anywhere in the games code (no countdown, best times or seconds)
        src=open(os.path.join(HERE,'..','games.js')).read()
        check('games.js has no countdown / best-time code', not re.search(r'gameSeconds|setBar|Date\.now\(\)\s*-\s*t0|best times?|seconds\b|\bsec\b', src))
        await pg.evaluate("App.gamePops=2"); await pg.click('.gcard[data-game=pop]'); await pg.wait_for_selector('#game.active')
        for _ in range(150):
            if await pg.locator('.gresult').count(): break
            ans=await pg.evaluate("(()=>{const q=document.querySelector('.pq-a'), f=document.querySelector('.pq-f'); return q? (+f.textContent - +q.textContent) : null})()")
            if ans is not None and await pg.locator(f'.bub[data-v="{ans}"]:not(.popped)').count():
                try: await pg.locator(f'.bub[data-v="{ans}"]:not(.popped)').first.dispatch_event('pointerdown')
                except Exception: pass
            await pg.wait_for_timeout(80)
        await pg.wait_for_selector('.gresult', timeout=10000)
        txt=await pg.text_content('.gresult')
        sc=await pg.evaluate("(()=>{const s=document.querySelector('#game .gscrim'), r=s&&s.getBoundingClientRect(), st=document.querySelector('#gameStage').getBoundingClientRect(), bg=s&&getComputedStyle(s).backgroundColor; return s? {covers: r.left<=st.left && r.top<=st.top && r.right>=st.right && r.bottom>=st.bottom, bg, card: !!s.querySelector('.gresult')} : null})()")
        alpha=float(re.findall(r'[\d.]+', sc['bg'])[-1]) if sc and sc['bg'].count(',')==3 or (sc and '/' in sc['bg']) else 1.0
        check('result card sits on a scrim that covers the board (nothing shows through)', sc and sc['covers'] and sc['card'] and alpha>=0.9, [sc, alpha])
        check('Friend Pop ends after its friends are found, counted not timed', '2 friends found' in txt and not re.search(r'second|\d\s*s\b', txt), txt)
        for _ in range(4):
            if not await pg.locator('#stickerReveal.active').count(): break
            await pg.click('#rvPack', force=True); await pg.wait_for_timeout(400); await pg.click('#rvOk'); await pg.wait_for_timeout(300)
        await pg.evaluate("App.gamePops=null"); await pg.click('.gresult [data-a=done]'); await pg.wait_for_selector('#play.active')
        check('Play hub identity is mustard (ink heading on a wooden plaque, mustard lacquer icon)', await pg.evaluate("(()=>{const h=getComputedStyle(document.querySelector('#play h1.toy-plaque')).color, i=document.querySelector('#playIc'); return [h, i.classList.contains('toy-lac--mustard'), i.querySelectorAll('svg').length]})()")==['rgb(43, 54, 116)', True, 1])
        check('Play hub: the scrim is gone', await pg.locator('#game .gscrim').count()==0)
        # "New!" only for games never played: an older save with best.pop (a timed best round) counts as played
        await pg.evaluate("(()=>{ const b=Fun.data.best; delete b.popTotal; b.pop=9; Games.renderHub(); })()")
        pc=await pg.text_content('.gcard[data-game=pop] .gc-best')
        check('Friend Pop played in an older version (best.pop): no "New!" badge', 'New' not in pc and '9 friends' in pc, pc)
        await pg.evaluate("(()=>{ const b=Fun.data.best; delete b.popTotal; delete b.pop; Games.renderHub(); })()")
        check('a game never played shows "New!"', 'New' in await pg.text_content('.gcard[data-game=pop] .gc-best'))
        await pg.click('#exitPlay'); await pg.wait_for_timeout(300)

        # ---- gate: non-readers hear/see "get a grown-up"; See all skills goes through it ----
        await door(pg); await pg.click('#doorAll'); await pg.wait_for_selector('#gate.active')
        check('gate: Bix says go get a grown-up, with a picture', 'grown-up' in await pg.text_content('#bixGate .bubble') and await pg.locator('#gateArt svg').count()==1)
        # step 1: press and hold for 3 seconds (letting go early does nothing); step 2: a written digit-picking instruction
        check('gate opens on the hold step: no question, no answer box yet', await pg.is_visible('#gateHold') and not await pg.is_visible('#gateA') and not await pg.is_visible('#gateQ') and await pg.evaluate('window.__gateAnswer') is None)
        hb=await pg.eval_on_selector('#gateHold','e=>{const r=e.getBoundingClientRect(); return [r.x+r.width/2, r.y+r.height/2, r.height]}')
        check('gate hold button is a big target (>= 60px)', hb[2]>=60, hb[2])
        await pg.click('#gateHold'); await pg.wait_for_timeout(300)
        check('gate: a quick tap does not open the question', not await pg.is_visible('#gateA') and 'Keep holding' in await pg.text_content('#gateMsg'), await pg.text_content('#gateMsg'))
        await pg.mouse.move(hb[0], hb[1]); await pg.mouse.down(); await pg.wait_for_timeout(1500); await pg.mouse.up(); await pg.wait_for_timeout(200)
        check('gate: letting go after 1.5 s starts again (bar empty, still locked)', not await pg.is_visible('#gateA') and await pg.eval_on_selector('#gateHold','e=>getComputedStyle(e).getPropertyValue("--p").trim()') in ('0','0.000'))
        await pg.mouse.down(); await pg.wait_for_timeout(1500)
        p=float(await pg.eval_on_selector('#gateHold','e=>getComputedStyle(e).getPropertyValue("--p")'))
        check('gate: the bar fills while she holds', 0.3<p<0.8, p)
        await pg.wait_for_timeout(1700); await pg.mouse.up(); await pg.wait_for_timeout(200)
        check('gate: after 3 s of holding the question appears', await pg.is_visible('#gateA') and await pg.is_visible('#gateQ'))
        qtxt=await pg.text_content('#gateQ .gw'); digs=await pg.eval_on_selector_all('#gateQ .gnum i','els=>els.map(e=>e.textContent)'); ans=await pg.evaluate('window.__gateAnswer')
        ords=re.findall(r'first|second|third|fourth|fifth', qtxt); want=''.join(digs[['first','second','third','fourth','fifth'].index(o)] for o in ords)
        check('gate question: pick 3 of 5 digits by ordinal words, in a given order (beyond the curriculum)', len(digs)==5 and len(ords)==3 and len(set(ords))==3 and str(ans)==want, [qtxt, digs, ans])
        check('gate question is not a sum or a number in words', not re.search(r'[+×−]|hundred|plus|times', qtxt))
        check('gate: one back button', await pg.locator('#gate button:has-text("Back"), #gate [aria-label="Back"]').count()==1)
        await pg.fill('#gateA','1'); await pg.click('#gateOk'); await pg.wait_for_timeout(200)
        check('gate: wrong answer stays locked with a new number and a kind message', await pg.locator('#gate.active').count()==1 and await pg.input_value('#gateA')=='' and 'new number' in await pg.text_content('#gateMsg') and await pg.is_visible('#gateA'))
        await pg.click('#gateBack'); await pg.wait_for_timeout(200)
        check('gate: Back returns to where it was opened (door)', await pg.locator('#door.active').count()==1)
        await pg.click('#doorAll'); await pg.wait_for_selector('#gate.active')
        check('gate: opening it again starts with the hold step', not await pg.is_visible('#gateA') and await pg.is_visible('#gateHold'))
        await pg.evaluate("document.querySelector('#gateA').value='1'"); await pg.evaluate("document.querySelector('#gateOk').click()"); await pg.wait_for_timeout(100)
        check('gate: Open does nothing before the hold', await pg.locator('#gate.active').count()==1)
        await pg.evaluate('window.__gateHold()'); await pg.fill('#gateA', str(await pg.evaluate('window.__gateAnswer'))); await pg.click('#gateOk'); await pg.wait_for_selector('#parent.active'); await pg.wait_for_timeout(500)
        inview=await pg.evaluate("(()=>{const r=document.querySelector('#guSkills').getBoundingClientRect(); return r.top>=-5 && r.top<innerHeight/2})()")
        check('See all skills: opens grown-ups at the skills list', inview)

        # ---- parent report from seeded history ----
        await pg.evaluate("document.querySelector('#parent').scrollTop=0")
        rep=await pg.evaluate("window.__report")
        check("report title: Mia's week", await pg.text_content('#repTitle')=='Mia’s week')
        check('days practised beads: 5 jade of 7', await pg.locator('#repDays .rep-beads .ws-bead').count()==7 and rep['daysPracticed']==5)
        check('days + minutes line', (await pg.text_content('#repDaysN'))=='5 of 7 days · 47 min', await pg.text_content('#repDaysN'))
        check('mastered this week: Small friends taking away', 'Small friends: taking away' in await pg.text_content('#repMastered'), await pg.text_content('#repMastered'))
        check('working on now: 72% with the 80% mark', '72% right' in await pg.text_content('#repNeed') and await pg.eval_on_selector('#repWorking .rep-bar b','e=>e.style.left')=='80%')
