        tiny=await pg.evaluate("[...document.querySelectorAll('#parent button, #parent select, #parent input:not([type=file]):not([type=range]), #parent .gu-nav a')].filter(e=>e.offsetParent && !e.closest('[hidden]')).map(e=>{const r=e.getBoundingClientRect(); return [e.id||e.className||e.tagName, Math.round(r.width), Math.round(r.height)]}).filter(x=>x[2]<44 || x[1]<44)")
        check('grown-ups: every button, toggle, field and the child switcher / + are >= 44px', not tiny, tiny)
